import React from 'react';
import {SectionTitle} from "../../../components/SectionTitle";
import {Skill} from "./Skill";
import {Container} from "../../../components/Container";
import {FlexWrapper} from "../../../components/FlexWrapper";
import {Fade} from "react-awesome-reveal";
import { S } from './Skills_Styles';



export  type SkillPropsType = {
    iconId: string,
    title: string
}

const SkillData = [
    {
        iconId: "javascript",
        title: "JAVACRIPT"
    },
    {
        iconId: "typeScript",
        title: "typescript"
    },
    {
        iconId: "mongo",
        title: "mongo db"
    },
    {
        iconId: "PostgreSQL",
        title: "PostgreSQL"
    },
    {
        iconId: "jest",
        title: "Jest"
    },
    {
        iconId: "express",
        title: "Express JS"
    },
    {
        iconId: "nest",
        title: "Nest JS"
    },
    {
        iconId: "docker",
        title: "Docker"
    },
    {
        iconId: "reactJs",
        title: "react js"
    },
    {
        iconId: "reactNative",
        title: "react nactive"
    },
    {
        iconId: "styledComponents",
        title: "Styled Components"
    },
    {
        iconId: "redux",
        title: "Redux"
    },
    {
        iconId: "git",
        title: "git"
    }

]

export const Skills = () => {
    return (
        <S.Skills>
            <Container>
                <SectionTitle>Skills</SectionTitle>
                <FlexWrapper wrap={"wrap"} justify={"center"} columnGap={"120px"} rowGap={"60px"}>
                    <Fade style={{ display: "flex",
                        }}
                          cascade damping={0.2}>
                        {SkillData.map((s, index)=> {
                            return (  <Skill iconId={s.iconId}
                                             title={s.title}
                                             key={index}
                                />
                            )
                        })}
                    </Fade>
                </FlexWrapper>
            </Container>
        </S.Skills>
    );
};



