import React from 'react';
import photoLight from "./../../../assets/images/main_light.png"
import {Button} from "../../../components/Button";
import {FlexWrapper} from "../../../components/FlexWrapper";
import {Container} from "../../../components/Container";
import {SectionTitle} from "../../../components/SectionTitle";
import { S } from './Main_Styles';
import Typewriter from 'typewriter-effect';
import Tilt from 'react-parallax-tilt';


export const Main = () => {
    return (
        <S.Main>
            <Container>
                <FlexWrapper justify={"space-between"} wrap={"wrap"}>
                    <S.TextBlock>
                        <S.MainTitle>
                            <p>DEVELOPER</p>
                            <Typewriter
                                options={{
                                    strings: ['DEVELOPER', 'Frontend Developer', 'Web Designer'],
                                    autoStart: true,
                                    loop: true,
                                    delay: 150
                                }}
                            />

                        </S.MainTitle>
                        <S.Name>Erica Font</S.Name>
                        <S.Text>Amet minim mollit non deserunt ullamco est sit aliqua dolor do amet sint. Velit officia
                            consequat duis enim velit mollit. Exercitation veniam consequat sunt.</S.Text>
                        <Button>Contact Me</Button>
                    </S.TextBlock>
                    {/*<Tilt*/}
                    {/*    className="parallax-effect-img"*/}
                    {/*    tiltMaxAngleX={40}*/}
                    {/*    tiltMaxAngleY={40}*/}
                    {/*    perspective={800}*/}
                    {/*    transitionSpeed={1500}*/}
                    {/*    scale={1.1}*/}
                    {/*    gyroscope={true}*/}
                    {/*>*/}
                    <S.Photo src={photoLight}/>
                        {/*</Tilt>*/}
                    <S.Descriptions>
                    <SectionTitle>About me</SectionTitle>
                        <S.TextDescriptions>The long barrow was built on land previously inhabited in the Mesolithic period. It
                            consisted
                            of a sub-rectangular earthen tumulus, estimated to have been 15 metres (50 feet) in length,
                            with a
                            chamber built from sarsen megaliths on its eastern end. Both inhumed and cremated human
                            remains were
                            placed within this chamber during the Neolithic period, representing at least nine or ten
                            individuals.
                        </S.TextDescriptions>
                    </S.Descriptions>
                </FlexWrapper>
            </Container>
        </S.Main>
    );
};

