import styled from "styled-components";
import {theme} from "../../../styles/Theme";
import {FlexWrapper} from "../../../components/FlexWrapper";
import {Button} from "../../../components/Button";

const Projects = styled.section`

    ${FlexWrapper} {
        gap: 27px;
    }
`

const Project= styled.div`
    flex-grow: 1;
    width: 522px;
    box-shadow: 2px 2px 32px 0 rgba(40, 38, 44, 0.15);
    background: ${theme.colors.secondaryBg};
    border-radius: 6px;
    padding-bottom: 32px;
`

const ImageWrapper= styled.div`
    position: relative;

    ${Button} {
        font-weight: 400;
        font-size: 10px;
        line-height: 140%;
        letter-spacing: 0.12em;
        text-transform: uppercase;
        text-align: center;
        color: ${theme.colors.fontBtnText};
        opacity: 0;
        position: absolute;
        left: 50%;
        top: 50%;
        transform: translate(-50%, -50%);
        transition: ${theme.animations.transition};


        &::before {
            width: 100%;
            height: 100%;
        }

    }

    &::before {
        content: "";
        position: absolute;
        left: 0;
        right: 0;
        top: 0;
        bottom: 0;

        backdrop-filter: blur(5px);
        background: rgba(255, 255, 255, 0.3);

        opacity: 0;
        transition: ${theme.animations.transition};
    }

    &:hover {

        &::before {
            opacity: 1;
        }

        ${Button} {
            opacity: 1;
            transform: translate(-50%, -50%);
        }

    }

    @media ${theme.media.tablet} {
        &::before {
            opacity: 1;
        }

        ${Button} {
            opacity: 1;
        }

    }
}


`

const Image= styled.img`
    width: 100%;
    height: 388px;
    object-fit: cover;
`

const Description= styled.div`
    padding: 0 8px 0 26px;
`

const Title= styled.h3``

const Text= styled.p``

const ListSkills = styled.ul`
    margin: 12px 0 20px;
    display: flex;
    flex-wrap: wrap;
    gap: 12px
    
   `

const SkillsItem = styled.li`
    border-radius: 4px;
    padding: 8px 16px;
    height: 30px;
    background-color: ${theme.colors.accent};
    font-size: 10px;
    line-height: 140%;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    text-align: center;
    color: ${theme.colors.fontBtnText};
`

export const S = {
    Projects,
    Project,
    ImageWrapper,
    Image,
    Description,
    Title,
    Text,
    ListSkills,
    SkillsItem
}