import React from 'react';
import {Icon} from "../../components/icon/Icon";
import {FlexWrapper} from "../../components/FlexWrapper";
import {Container} from "../../components/Container";
import {S} from "./Footer_Styles"


const  socialItemData = [
    {
        iconId: "email",
        title: "gmail"
    },
    {
        iconId: "linkedin",
        title: "linkedin"
    },
    {
        iconId: "gitHub",
        title: "GITHUB"
    }
]

export const Footer: React.FC = () => {
    return (
        <S.Footer>
            <Container>
                <FlexWrapper direction={"column"} rowGap={"50px"}>
                    <S.SocialList>
                        {socialItemData.map((s, index) => {
                            return <S.SocialItem>
                                <S.SocialList>
                                    <Icon height={"38"} key={index}
                                          width={"38"}
                                          viewBox={"0 0 38 38"}
                                          iconId={s.iconId}/>
                                </S.SocialList>
                                <S.SocialTitle>{s.title}</S.SocialTitle>
                            </S.SocialItem>
                        })}
                    </S.SocialList>
                    <S.BlockLink>
                        <S.SocialLink href="">Projects</S.SocialLink>
                        <S.SocialLink href="">Contact</S.SocialLink>
                    </S.BlockLink>
                    <S.Copyright>WEB DEVELOPER 2021</S.Copyright>
                </FlexWrapper>
            </Container>
        </S.Footer>
    );
};

