import React from 'react';
import styled from "styled-components";
import {theme} from "../../../styles/Theme";

const items = [
    {
        title: "Home",
        href: "home"
    },
    {
        title: "Projects",
        href: "projects"
    },
    {
        title: "Contact",
        href: "contact"
    }
]

export const Menu: React.FC = () => {
    return (
        <StyledMenu>
            {items.map((item, index) => {
                return <MenuItem>
                    <Link href={item.href}>
                        {item.title}
                    </Link>
                </MenuItem>
            })}
        </StyledMenu>
    );
};

const StyledMenu = styled.ul`
    width: 100vw;
    display: flex;
    gap: 87px;
    
    li:first-child {
        flex-grow: 1;
        text-align: left;
    }
    
    @media ${theme.media.mobile} {
        gap: 0;
       
    }
   
`


const Link = styled.a`
    font-weight: 500;
    font-size: 16px;
    color: ${theme.colors.fontText};
    border-radius: 6px;
    padding: 12px 10px 13px 10px;
    width: 90px;
    height: 45px;
    display: inline-block;
    text-align: center;
    

    

    &:hover{
        background-color: ${theme.colors.accent};
        color: ${theme.colors.fontBtnText};


    }
`

const MenuItem = styled.li`
  
`